// Fibonacci ingenuo: cada llamada resuelve todo desde cero
let llamadas = 0;
function fib(n) {
  llamadas++;
  if (n < 2) return n;                  // casos base: fib(0) = 0 y fib(1) = 1
  return fib(n - 1) + fib(n - 2);       // paso recursivo
}

for (const n of [10, 20, 25, 30, 35]) {
  llamadas = 0;
  const t0 = performance.now();
