// Fibonacci con memoria: la libreta es un Map de «n» a «fib(n)»
let llamadas = 0;
const libreta = new Map();

function fibMemo(n) {
  llamadas++;
  if (n < 2) return n;
  if (libreta.has(n)) return libreta.get(n);       // ya estaba anotado: lo leo y listo
  const resultado = fibMemo(n - 1) + fibMemo(n - 2);
  libreta.set(n, resultado);                        // lo anoto antes de devolverlo
  return resultado;
}

for (const n of [10, 20, 30, 40]) {
  llamadas = 0; libreta.clear();
  const t0 = performance.now();
  const r = fibMemo(n);
  const ms = performance.now() - t0;
  console.log(`fibMemo(${n}) = ${r}   llamadas: ${llamadas}   anotaciones: ${libreta.size}   tiempo: ${ms.toFixed(3)} ms`);
}

// El mismo truco, escrito una sola vez para cualquier función de UN argumento
function memoizar(f) {
  const guardado = new Map();
  return function (x) {
    if (guardado.has(x)) return guardado.get(x);
    const r = f(x);
    guardado.set(x, r);
    return r;
  };
}
// Ojo: para que memoizar sirva, la función recursiva tiene que llamarse a sí misma a través de la versión memoizada
const fib2 = memoizar(n => (n < 2 ? n : fib2(n - 1) + fib2(n - 2)));
console.log("fib2(40) =", fib2(40));

