// De abajo hacia arriba: una tabla que se llena en orden, sin recursión
function fibTabla(n) {
  const t = new Array(n + 1).fill(0);
  t[1] = 1;
  for (let i = 2; i <= n; i++) t[i] = t[i - 1] + t[i - 2];   // cada celda usa las dos anteriores
  return t[n];
}
// Y como solo hacen falta las dos últimas, la tabla entera sobra
function fibDosVariables(n) {
  let anterior = 0, actual = 1;
  for (let i = 0; i < n; i++) [anterior, actual] = [actual, anterior + actual];
  return anterior;
}
console.log(fibTabla(40), fibDosVariables(40));

