// Voraz: ordenar por valor/peso y meter mientras entre
function voraz(items, cap) {
  const orden = items.slice().sort((x, y) => y.valor / y.peso - x.valor / x.peso);
  let resto = cap, total = 0; const elegidos = [];
  for (const it of orden) if (it.peso <= resto) { elegidos.push(it.id); resto -= it.peso; total += it.valor; }
  return { elegidos, total };
}

// Programación dinámica: tabla[i][w] = mejor valor usando los primeros i pedidos con w de capacidad
function mochila(items, cap) {
  const n = items.length;
  const tabla = Array.from({ length: n + 1 }, () => new Array(cap + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    const { peso, valor } = items[i - 1];
    for (let w = 0; w <= cap; w++) {
      tabla[i][w] = tabla[i - 1][w];                                   // opción 1: no llevarlo
      if (peso <= w) tabla[i][w] = Math.max(tabla[i][w], tabla[i - 1][w - peso] + valor); // opción 2: llevarlo
    }
  }
  // Reconstruir: de la última celda hacia atrás
  const elegidos = []; let w = cap;
  for (let i = n; i >= 1; i--) if (tabla[i][w] !== tabla[i - 1][w]) { elegidos.unshift(items[i - 1].id); w -= items[i - 1].peso; }
  return { total: tabla[n][cap], elegidos, tabla };
}
