  ["P07", 275, 170], ["P08", 190, 120], ["P09", 40, 22], ["P10", 205, 140], ["P11", 330, 200], ["P12", 95, 65],
].map(([id, peso, valor]) => ({ id, peso, valor }));
const CAPACIDAD = 1000;

// Programación dinámica: tabla[i][w] = mejor valor con los primeros i pedidos y w kg de capacidad
function mochila(items, cap) {
  const n = items.length;
  const tabla = Array.from({ length: n + 1 }, () => new Int32Array(cap + 1));
  for (let i = 1; i <= n; i++) {
    const { peso, valor } = items[i - 1];
    for (let w = 0; w <= cap; w++) {
      tabla[i][w] = tabla[i - 1][w];
      if (peso <= w) tabla[i][w] = Math.max(tabla[i][w], tabla[i - 1][w - peso] + valor);
    }
  }
  const elegidos = []; let w = cap;
  for (let i = n; i >= 1; i--) if (tabla[i][w] !== tabla[i - 1][w]) { elegidos.unshift(items[i - 1].id); w -= items[i - 1].peso; }
  return { total: tabla[n][cap], elegidos, celdas: (n + 1) * (cap + 1) };
}

// Fuerza bruta: probar los 2^n subconjuntos (cada bit de «m» dice si el pedido i va o no)
function fuerzaBruta(items, cap) {
  let mejor = 0, mascara = 0;
  for (let m = 0; m < 2 ** items.length; m++) {
    let peso = 0, valor = 0;
    for (let i = 0; i < items.length; i++) if (m & (1 << i)) { peso += items[i].peso; valor += items[i].valor; }
    if (peso <= cap && valor > mejor) { mejor = valor; mascara = m; }
  }
  return { total: mejor, elegidos: items.filter((_, i) => mascara & (1 << i)).map(x => x.id), subconjuntos: 2 ** items.length };
}

// Voraz: lo que haría un despachante apurado, primero lo que más paga por kilo
function voraz(items, cap) {
  const orden = items.slice().sort((x, y) => y.valor / y.peso - x.valor / x.peso);
